func (c *CLab) reconcileNodes(ctx context.Context, plan *applyPlan) error {
	if plan == nil || plan.currentNodes == nil {
		return nil
	}

	for nodeName := range plan.currentNodes {
		node, exists := c.Nodes[nodeName]
		if !exists {
			continue
