func (c *CLab) prepareLabManagementNetwork(
	ctx context.Context,
	existing ...clabtypes.ExistingAddress,
) error {
	if err := c.CreateNetwork(ctx); err != nil {
		return err
	}

	if err := c.allocateLabManagementIPs(ctx, existing); err != nil {
