+topology:
+  nodes:
+    n1:
+      kind: linux
+      image: alpine
+  links:
+    - type: mgmt-net
+      network: mgmtnet-dropped-b
+      endpoint:
+        node: n1
+        interface: eth1
+      host-interface: n1-eth1
+`)
+
